CREATE OR REPLACE FUNCTION public.do_side_action(action_type text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ declare p public.profiles;cost int;gain_money numeric(12,2):=0;gain_bottles int:=0;gain_xp int:=0;ok boolean:=true;label text;regen int; begin select * into p from public.profiles where id=auth.uid() for update; if p.id is null or p.is_banned then raise exception 'Zugriff gesperrt';end if; if p.collection_ends_at is not null then raise exception 'Der Einkaufswagen ist noch unterwegs oder nicht ausgeladen';end if; if p.last_side_action_at is not null and p.last_side_action_at>now()-interval '60 seconds' then raise exception 'Du brauchst kurz Luft. Nächste Aktion in spätestens 60 Sekunden';end if; regen:=floor(extract(epoch from(now()-p.energy_updated_at))/60)::int; if regen>0 then p.energy:=least(100,p.energy+regen);end if; case action_type when 'newspapers' then cost:=4;gain_money:=round((0.30+random()*0.55+p.speech_skill*0.02)::numeric,2);gain_xp:=3;label:='Abendblätter verteilt'; when 'sorting' then cost:=6;gain_bottles:=2+floor(random()*5)::int+floor(p.streetwise/4)::int;gain_xp:=4;label:='Pfand im Hinterhof sortiert'; when 'parking' then cost:=7;gain_money:=round((0.55+random()*1.10+p.social_skill*0.03)::numeric,2);gain_xp:=5;label:='Einkaufswagen bewacht'; when 'windshield' then cost:=5;gain_money:=round((0.25+random()*0.45+p.speech_skill*0.015)::numeric,2);gain_xp:=3;label:='Scheiben an der Ampel gewischt'; else raise exception 'Unbekannte Kiezaktion';end case; if p.energy<cost then raise exception 'Nicht genug Energie';end if; update public.profiles set energy=p.energy-cost,energy_updated_at=now(),money=least(cash_capacity,greatest(0,money+gain_money)),bottles=bottles+gain_bottles,xp=xp+gain_xp,last_side_action_at=now() where id=p.id returning * into p; insert into public.side_action_log(user_id,action_type,success,money_change,bottle_change,xp_change) values(p.id,action_type,ok,gain_money,gain_bottles,gain_xp); return jsonb_build_object('success',ok,'label',label,'money',gain_money,'bottles',gain_bottles,'xp',gain_xp,'energy_cost',cost,'profile',to_jsonb(p)); end $function$;
